CREATE DATABASE IF NOT EXISTS job_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE job_portal;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('candidate','recruiter') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE companies (id INT AUTO_INCREMENT PRIMARY KEY,recruiter_id INT NOT NULL UNIQUE,company_name VARCHAR(150) NOT NULL,description TEXT,location VARCHAR(150) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_company_recruiter FOREIGN KEY(recruiter_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE jobs (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,requirements TEXT,location VARCHAR(150) NOT NULL,salary VARCHAR(100),job_type ENUM('Full-time','Part-time','Contract','Internship','Remote') NOT NULL DEFAULT 'Full-time',posted_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_jobs_location(location),INDEX idx_jobs_type(job_type),CONSTRAINT fk_job_company FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE resumes (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,file_name VARCHAR(255) NOT NULL,file_path VARCHAR(255) NOT NULL,uploaded_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_resume_user(user_id),CONSTRAINT fk_resume_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE applications (id INT AUTO_INCREMENT PRIMARY KEY,job_id INT NOT NULL,user_id INT NOT NULL,resume_id INT NOT NULL,status ENUM('Applied','Under Review','Shortlisted','Rejected','Selected') NOT NULL DEFAULT 'Applied',applied_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_application(job_id,user_id),INDEX idx_application_user(user_id),CONSTRAINT fk_application_job FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,CONSTRAINT fk_application_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_application_resume FOREIGN KEY(resume_id) REFERENCES resumes(id) ON DELETE RESTRICT);
